at":"van_phong_pham","phone":null,"pid":"ChIJjzy0--UvdTERP22roT4ONaE","src":null,"old":"Tân Phú","e":"Cửa hàng stationery/quà tặng/sổ-bút ở shop 2F-51 tầng 2 Crescent Mall; không trùng Nhà sách Phương Nam tầng 3 cùng mall.","map":"https://www.google.com/maps/search/?api=1&query=TYPO%20%E2%80%93%20Crescent%20Mall%20Shop%202F-51%2C%20Crescent%20Mall%2C%20101%20T%C3%B4n%20D%E1%BA%ADt%20Ti%C3%AAn%20Qu%E1%BA%ADn%207%20TP%20H%E1%BB%93%20Ch%C3%AD%20Minh%20Vi%E1%BB%87t%20Nam&query_place_id=ChIJjzy0--UvdTERP22roT4ONaE","url":"https://www.google.com/maps/search/?api=1&query=TYPO%20%E2%80%93%20Crescent%20Mall%20Shop%202F-51%2C%20Crescent%20Mall%2C%20101%20T%C3%B4n%20D%E1%BA%ADt%20Ti%C3%AAn%20Qu%E1%BA%ADn%207%20TP%20H%E1%BB%93%20Ch%C3%AD%20Minh%20Vi%E1%BB%87t%20Nam&query_place_id=ChIJjzy0--UvdTERP22roT4ONaE","key":"gmaps:ChIJjzy0--UvdTERP22roT4ONaE"},{"n":"Văn phòng phẩm Duy Tân","s":"1283/17/3A Huỳnh Tấn Phát","w":"Phú Thuận","cat":"van_phong_pham","phone":"0914635515","pid":null,"src":"https://vppduytan.vn/shop/","old":"Phú Thuận","e":"Trang danh mục Cửa hàng công bố địa chỉ và số điện thoại; mô tả website có nội dung mẫu không liên quan, cần gọi xác nhận bán VPP tại cửa hàng.","map":null,"url":"https://vppduytan.vn/shop/","key":"official:hcm:q7:r1:duy-tan-1283-17-3a"}]'::jsonb)
 AS c(n text,s text,w text,cat text,phone text,pid text,src text,old text,e text,map text,url text,key text)
), vetted AS (
 SELECT c.*
 FROM candidates c JOIN public.sales_hcm_old_wards w
 ON w.province='TP Hồ Chí Minh' AND w.legacy_district='Quận 7'
 AND w.ward_new=c.w AND w.active
 WHERE c.w IN ('Tân Hưng','Tân Thuận','Tân Mỹ','Phú Thuận')
 AND c.cat IN ('nha_sach','van_phong_pham') AND c.url LIKE 'https://%'
 AND NOT EXISTS (
  SELECT 1 FROM public.field_prospects p
  WHERE p.research_source_key=c.key
  OR (c.pid IS NOT NULL AND p.google_place_id=c.pid)
  OR (c.phone IS NOT NULL AND p.phone IS NOT NULL AND
     regexp_replace(p.phone,'[^0-9]','','g')=regexp_replace(c.phone,'[^0-9]','','g'))
  OR (p.province='TP Hồ Chí Minh' AND p.district='Quận 7' AND (
   lower(btrim(p.name))=lower(btrim(c.n))
   OR lower(btrim(split_part(p.address_line,', phường',1)))=lower(btrim(c.s))
   OR lower(p.address_line) LIKE lower(c.s||',%')
  ))
 )
 AND NOT EXISTS (
  SELECT 1 FROM public.customers k
  WHERE (c.phone IS NOT NULL AND k.phone IS NOT NULL AND
    regexp_replace(k.phone,'[^0-9]','','g')=regexp_replace(c.phone,'[^0-9]','','g'))
  OR (k.province='TP Hồ Chí Minh' AND k.district='Quận 7'
     AND (lower(btrim(k.name))=lower(btrim(c.n))
       OR lower(k.address_line) LIKE lower(c.s||',%')))
 )
), inserted AS (
 INSERT INTO public.field_prospects
 (owner_sub,name,address_line,province,district,category,phone,note,status,source_kind,
  research_source_key,research_source_url,research_batch,ward_new,address_legacy,google_maps_url,google_place_id)
 SELECT 'ef943de4-18f7-49ef-8340-eefb18855534',c.n,
 c.s||', phường '||c.w||', TP. Hồ Chí Minh',
 'TP Hồ Chí Minh','Quận 7',c.cat,c.phone,
 'Rà nguồn online ngày 22/11/2026: '||c.e||
 '. CHƯA GHÉ, CHƯA XÁC MINH bảng hiệu, hoạt động hoặc GPS thực địa. Google place ID chỉ là dữ liệu nghiên cứu, không phải check-in. Nguồn: '||c.url,
 'new','manual',c.key,c.url,'2026-11-22-hcm-old-q7-round1-189',
 c.w,c.s||', '||CASE WHEN coalesce(c.old,'')='' THEN '' ELSE c.old||', ' END||'Quận 7 cũ, TP.HCM cũ',
 c.map,c.pid
 FROM vetted c
 ON CONFLICT DO NOTHING RETURNING name,ward_new,category
)
SELECT ward_new,category,count(*)::int AS added,
 string_agg(name,'; ' ORDER BY name) AS shops
FROM inserted GROUP BY ward_new,category ORDER BY ward_new,category;
